/** П1 «Как курица лапкой»: Миша (1) and his partner (2) check their lists against each other; T is the teacher.
 *  Lines p1-01…p1-31 in order; p1-32 Миша greets a teacher who came in openly, p1-33 asks them instead of the call (15–17);
 *  p1-tq the teacher asks what the question is, p1-ta the ready answer. Text: ~/temp/П1-курица.txt */
export interface DialogueLine { id: string; who: 1 | 2 | 'T'; write: string | null; ms: Record<string, number>; text: string }
/** П4 «Трёп»: they begin checking (p4-01…07), drift into chatter by who sits there — м-м p4-08…29 football, ж-ж p4-30…47
 *  the party, ж-м p4-48…69 the rabbit (1 the girl) — and wake up at the end (p4-70…76, one writes out their list);
 *  a teacher coming in openly before that gets p4-77…89 instead: they check for real. Text: ~/temp/П4-трёп.txt */
export const CHAT: DialogueLine[] = [
  {"id": "p4-01", "who": 1, "write": null, "ms": {"dasha": 1620, "anton": 1515, "masha": 1698, "ermil": 1384}, "text": "Ну что, сверяемся?"},
  {"id": "p4-02", "who": 2, "write": null, "ms": {"dasha": 1698, "anton": 1698, "masha": 1829, "ermil": 1489}, "text": "Давай. У тебя сколько?"},
  {"id": "p4-03", "who": 1, "write": null, "ms": {"dasha": 2429, "anton": 2403, "masha": 2638, "ermil": 2377}, "text": "Четыре. Стороны и диагонали."},
  {"id": "p4-04", "who": 2, "write": null, "ms": {"dasha": 5564, "anton": 5538, "masha": 6008, "ermil": 5721}, "text": "У меня тоже четыре, только другие. Стороны есть, диагоналей нет. Зато углы."},
  {"id": "p4-05", "who": 1, "write": null, "ms": {"dasha": 5460, "anton": 5277, "masha": 5642, "ermil": 5172}, "text": "Угол а равен углу цэ — вижу. А внизу что? Это бэ или восьмёрка?"},
  {"id": "p4-06", "who": 2, "write": null, "ms": {"dasha": 2560, "anton": 2560, "masha": 2691, "ermil": 2586}, "text": "Бэ. Угол бэ равен углу дэ."},
  {"id": "p4-07", "who": 1, "write": null, "ms": {"dasha": 4519, "anton": 4389, "masha": 4702, "ermil": 4493}, "text": "Ну и почерк. Ладно, значит, вместе у нас… раз, два…"},
  {"id": "p4-08", "who": 2, "write": null, "ms": {"anton": 2377, "ermil": 2247}, "text": "Слушай, а ты в субботу чего не пришёл?"},
  {"id": "p4-09", "who": 1, "write": null, "ms": {"anton": 3500, "ermil": 3448}, "text": "Не пустили, бабушка приезжала. Ну и как сыграли?"},
  {"id": "p4-10", "who": 2, "write": null, "ms": {"anton": 862, "ermil": 836}, "text": "Семь — пять."},
  {"id": "p4-11", "who": 1, "write": null, "ms": {"anton": 836, "ermil": 705}, "text": "Кто кого?"},
  {"id": "p4-12", "who": 2, "write": null, "ms": {"anton": 758, "ermil": 758}, "text": "Они нас."},
  {"id": "p4-13", "who": 1, "write": null, "ms": {"anton": 1881, "ermil": 1776}, "text": "Семь?! А кто на воротах стоял?"},
  {"id": "p4-14", "who": 2, "write": null, "ms": {"anton": 601, "ermil": 601}, "text": "Костя."},
  {"id": "p4-15", "who": 1, "write": null, "ms": {"anton": 1776, "ermil": 1855}, "text": "А, ну тогда всё понятно."},
  {"id": "p4-16", "who": 2, "write": null, "ms": {"anton": 7549, "ermil": 7628}, "text": "Да там вообще... А за них ещё Рустам пришёл, здоровый такой. Он точно в восьмом? Кажется, что ему лет восемнадцать."},
  {"id": "p4-17", "who": 1, "write": null, "ms": {"anton": 1280, "ermil": 1306}, "text": "Это который с бородой?"},
  {"id": "p4-18", "who": 2, "write": null, "ms": {"anton": 4833, "ermil": 5016}, "text": "С бородой. Мы говорим: так нечестно. А он: «Борода не играет»."},
  {"id": "p4-19", "who": 1, "write": null, "ms": {"anton": 1463, "ermil": 1463}, "text": "Мда, гениально."},
  {"id": "p4-20", "who": 2, "write": null, "ms": {"anton": 9796, "ermil": 9691}, "text": "А последний гол - просто песня. Костя начал мяч выносить и прямо Максу в спину попал. А от него — под удар их нападающему. Ну и всё, семь — пять."},
  {"id": "p4-21", "who": 1, "write": null, "ms": {"anton": 1933, "ermil": 1985}, "text": "То есть Костя им ещё и помог."},
  {"id": "p4-22", "who": 2, "write": null, "ms": {"anton": 1672, "ermil": 1698}, "text": "Он сказал, это тактика была."},
  {"id": "p4-23", "who": 1, "write": null, "ms": {"anton": 1149, "ermil": 1045}, "text": "Какая тактика?"},
  {"id": "p4-24", "who": 2, "write": null, "ms": {"anton": 2038, "ermil": 2090}, "text": "Не знаю. Он сам не знает."},
  {"id": "p4-25", "who": 1, "write": null, "ms": {"anton": 1254, "ermil": 1176}, "text": "В эту субботу идём?"},
  {"id": "p4-26", "who": 2, "write": null, "ms": {"anton": 2612, "ermil": 2664}, "text": "Идём. Только Костю на ворота не ставим."},
  {"id": "p4-27", "who": 1, "write": null, "ms": {"anton": 1071, "ermil": 1045}, "text": "Давай я встану."},
  {"id": "p4-28", "who": 2, "write": null, "ms": {"anton": 4493, "ermil": 4519}, "text": "Ты? Ты в прошлый раз в воротах спиной стоял, с кем-то по телефону болтал."},
  {"id": "p4-29", "who": 1, "write": null, "ms": {"anton": 1228, "ermil": 1280}, "text": "Это мама звонила!"},
  {"id": "p4-30", "who": 2, "write": null, "ms": {"dasha": 2273, "masha": 2560}, "text": "Слушай, а ты у Кати до конца была?"},
  {"id": "p4-31", "who": 1, "write": null, "ms": {"dasha": 3657, "masha": 3814}, "text": "Нет, меня в девять забрали. А что? Что-то было?"},
  {"id": "p4-32", "who": 2, "write": null, "ms": {"dasha": 2900, "masha": 3082}, "text": "Было. Лёша пришёл. В белой рубашке."},
  {"id": "p4-33", "who": 1, "write": null, "ms": {"dasha": 1933, "masha": 2064}, "text": "В белой? На день рождения?"},
  {"id": "p4-34", "who": 2, "write": null, "ms": {"dasha": 5198, "masha": 5460}, "text": "Да. И стоит у стены. Весь вечер стоит. Все танцуют, а он стоит."},
  {"id": "p4-35", "who": 1, "write": null, "ms": {"dasha": 1411, "masha": 1489}, "text": "Ну! это Лёша."},
  {"id": "p4-36", "who": 2, "write": null, "ms": {"dasha": 6504, "masha": 7053}, "text": "Подожди. И тут Катя включает ту песню. Ну, которую она всё время слушает. И идёт прямо к нему."},
  {"id": "p4-37", "who": 1, "write": null, "ms": {"dasha": 862, "masha": 862}, "text": "Да ладно."},
  {"id": "p4-38", "who": 2, "write": null, "ms": {"dasha": 2247, "masha": 2429}, "text": "А он отходит и наливает себе сок."},
  {"id": "p4-39", "who": 1, "write": null, "ms": {"dasha": 627, "masha": 653}, "text": "Чего?"},
  {"id": "p4-40", "who": 2, "write": null, "ms": {"dasha": 4702, "masha": 5016}, "text": "Он думал, она к столу идёт. Отошёл, чтобы не мешать. И налил себе сок."},
  {"id": "p4-41", "who": 1, "write": null, "ms": {"dasha": 993, "masha": 1019}, "text": "Не может быть."},
  {"id": "p4-42", "who": 2, "write": null, "ms": {"dasha": 5669, "masha": 5982}, "text": "Может. Она так и стоит посреди комнаты. Потом говорит: «Лёш, я вообще-то к тебе»."},
  {"id": "p4-43", "who": 1, "write": null, "ms": {"dasha": 601, "masha": 601}, "text": "А он?"},
  {"id": "p4-44", "who": 2, "write": null, "ms": {"dasha": 1620, "masha": 1724}, "text": "А он ей: «Будешь сок?»"},
  {"id": "p4-45", "who": 1, "write": null, "ms": {"dasha": 3265, "masha": 3213}, "text": "Всё, не могу. И что, танцевали в итоге?"},
  {"id": "p4-46", "who": 2, "write": null, "ms": {"dasha": 5695, "masha": 6217}, "text": "Танцевали. Он ей на ногу пару раз наступил, вроде. А она потом сказала, что это было мило."},
  {"id": "p4-47", "who": 1, "write": null, "ms": {"dasha": 1829, "masha": 1881}, "text": "Мило… Ну Катя даёт."},
  {"id": "p4-48", "who": 1, "write": null, "ms": {"dasha": 1802, "masha": 2090}, "text": "А у нас вчера кролик появился."},
  {"id": "p4-49", "who": 2, "write": null, "ms": {"anton": 1593, "ermil": 1411}, "text": "В смысле — появился."},
  {"id": "p4-50", "who": 1, "write": null, "ms": {"dasha": 3631, "masha": 3997}, "text": "Родители купили. Младшей сестре, у неё день рождения."},
  {"id": "p4-51", "who": 2, "write": null, "ms": {"anton": 914, "ermil": 862}, "text": "Настоящий?"},
  {"id": "p4-52", "who": 1, "write": null, "ms": {"dasha": 5094, "masha": 5433}, "text": "Нет, плюшевый. Конечно, настоящий. Серый, уши большие такие."},
  {"id": "p4-53", "who": 2, "write": null, "ms": {"anton": 888, "ermil": 810}, "text": "Как назвали?"},
  {"id": "p4-54", "who": 1, "write": null, "ms": {"dasha": 1776, "masha": 1829}, "text": "Она назвала. Пельмень."},
  {"id": "p4-55", "who": 2, "write": null, "ms": {"anton": 967, "ermil": 888}, "text": "Почему Пельмень?"},
  {"id": "p4-56", "who": 1, "write": null, "ms": {"dasha": 3082, "masha": 3187}, "text": "Говорит, похож. Сидит — и правда похож."},
  {"id": "p4-57", "who": 2, "write": null, "ms": {"anton": 1463, "ermil": 1515}, "text": "А ты как хотела назвать?"},
  {"id": "p4-58", "who": 1, "write": null, "ms": {"dasha": 2090, "masha": 2194}, "text": "Граф. Но кто меня спрашивал."},
  {"id": "p4-59", "who": 2, "write": null, "ms": {"anton": 993, "ermil": 993}, "text": "Граф Пельмень."},
  {"id": "p4-60", "who": 1, "write": null, "ms": {"dasha": 5512, "masha": 5773}, "text": "О. Так и будем звать. Только он ночью провод от зарядки перегрыз. Мой."},
  {"id": "p4-61", "who": 2, "write": null, "ms": {"anton": 888, "ermil": 836}, "text": "А мама что?"},
  {"id": "p4-62", "who": 1, "write": null, "ms": {"dasha": 4937, "masha": 5381}, "text": "Мама говорит: «Сами хотели кролика». А я не хотела! Это сестра хотела."},
  {"id": "p4-63", "who": 2, "write": null, "ms": {"anton": 1515, "ermil": 1515}, "text": "И как теперь без зарядки?"},
  {"id": "p4-64", "who": 1, "write": null, "ms": {"dasha": 2325, "masha": 2508}, "text": "Взяла папину. Он пока не знает."},
  {"id": "p4-65", "who": 2, "write": null, "ms": {"anton": 1620, "ermil": 1515}, "text": "А его на руки брать можно?"},
  {"id": "p4-66", "who": 1, "write": null, "ms": {"dasha": 7863, "masha": 8620}, "text": "Можно, только он лягается. Сестра посадила его в кукольную коляску, а он выпрыгнул и под диван. Час доставали."},
  {"id": "p4-67", "who": 2, "write": null, "ms": {"anton": 731, "ermil": 627}, "text": "Покажешь?"},
  {"id": "p4-68", "who": 1, "write": null, "ms": {"dasha": 2821, "masha": 3213}, "text": "Приходи. Только за зарядкой своей в оба смотри."},
  {"id": "p4-69", "who": 2, "write": null, "ms": {"anton": 1593, "ermil": 1593}, "text": "Хорошо, договорились."},
  {"id": "p4-70", "who": 1, "write": null, "ms": {"dasha": 2194, "anton": 2220, "masha": 2456, "ermil": 2038}, "text": "Ой, смотри, время заканчивается."},
  {"id": "p4-71", "who": 2, "write": null, "ms": {"dasha": 1933, "anton": 2064, "masha": 2168, "ermil": 2247}, "text": "Мы же так ничего и не проверили."},
  {"id": "p4-72", "who": 1, "write": "AD = BC; AB = CD; AO = OC; BO = OD", "ms": {"dasha": 2821, "anton": 2821, "masha": 3082, "ermil": 2743}, "text": "Давай я просто своё выпишу. Там всё нормально."},
  {"id": "p4-73", "who": 2, "write": null, "ms": {"dasha": 888, "anton": 940, "masha": 940, "ermil": 836}, "text": "А мои углы?"},
  {"id": "p4-74", "who": 1, "write": null, "ms": {"dasha": 888, "anton": 914, "masha": 940, "ermil": 758}, "text": "Это какие?"},
  {"id": "p4-75", "who": 2, "write": null, "ms": {"dasha": 1829, "anton": 1985, "masha": 2011, "ermil": 1933}, "text": "Угол а равен углу цэ."},
  {"id": "p4-76", "who": 1, "write": "∠A = ∠C", "ms": {"dasha": 1384, "anton": 1280, "masha": 1411, "ermil": 1280}, "text": "Хорошо, берём."},
  {"id": "p4-77", "who": "T", "write": null, "ms": {"alena": 2691}, "text": "Так, как у вас дела? Проверили уже?"},
  {"id": "p4-78", "who": 1, "write": null, "ms": {"dasha": 3396, "anton": 3370, "masha": 3631, "ermil": 3161}, "text": "Здравствуйте, Татьяна Алексеевна. Да… почти."},
  {"id": "p4-79", "who": 2, "write": null, "ms": {"dasha": 810, "anton": 731, "masha": 862, "ermil": 784}, "text": "Проверяем..."},
  {"id": "p4-80", "who": "T", "write": null, "ms": {"alena": 8255}, "text": "Что-то у вас доска совсем пустая. Нужно уже ускоряться. По очереди, по одному наблюдению, и сразу записывайте. Всё понятно?"},
  {"id": "p4-81", "who": 1, "write": null, "ms": {"dasha": 2247, "anton": 2194, "masha": 2273, "ermil": 2064}, "text": "Да, сейчас. Начинаем."},
  {"id": "p4-82", "who": 2, "write": "AD = BC", "ms": {"dasha": 1280, "anton": 1332, "masha": 1384, "ermil": 1358}, "text": "А-дэ равно бэ-цэ."},
  {"id": "p4-83", "who": 1, "write": "AB = CD", "ms": {"dasha": 1202, "anton": 1280, "masha": 1332, "ermil": 1332}, "text": "А-бэ равно цэ-дэ."},
  {"id": "p4-84", "who": 2, "write": "∠A = ∠C", "ms": {"dasha": 3239, "anton": 3265, "masha": 3553, "ermil": 3370}, "text": "Угол а равен углу цэ. Этого у тебя не было."},
  {"id": "p4-85", "who": 1, "write": "AO = OC", "ms": {"dasha": 3187, "anton": 3344, "masha": 3474, "ermil": 3187}, "text": "Тогда а-о равно о-цэ. А этого не было у тебя."},
  {"id": "p4-86", "who": 2, "write": "∠B = ∠D", "ms": {"dasha": 3344, "anton": 3422, "masha": 3683, "ermil": 3500}, "text": "Угол бэ равен углу дэ. Та самая «восьмёрка»."},
  {"id": "p4-87", "who": 1, "write": "BO = OD", "ms": {"dasha": 1411, "anton": 1593, "masha": 1567, "ermil": 1463}, "text": "Бэ-о равно о-дэ."},
  {"id": "p4-88", "who": 2, "write": null, "ms": {"dasha": 3527, "anton": 3474, "masha": 3788, "ermil": 3422}, "text": "Смотри: у каждого было по четыре, а вместе — шесть."},
  {"id": "p4-89", "who": 1, "write": null, "ms": {"dasha": 1332, "anton": 1332, "masha": 1411, "ermil": 1202}, "text": "Да, отлично."},
];

/** Ч2 «Шестая — самая коварная» (b10, the four where Аня sits): 1–3 whoever, 4 is always Аня. No teacher in it.
 *  Text: ~/temp/Ч2-шестая.txt */
export interface FourLine { id: string; who: 1 | 2 | 3 | 4; write: string | null; ms: Record<string, number>; text: string }
/** Ч1 «Ловушка трапеции» (b10, the other four): 1 Организатор, 2 Сомневающийся (a girl: Лена), 3 Третий, 4 Шутник; T the teacher:
 *  c1-t0 «Какие у вас вопросы?», c1-ta1… the ready answer (drawing as it goes), c1-tok the praise. 38–39 instead of 18–19
 *  when the teacher is in the room as they'd call. Text: ~/temp/Ч1-трапеция.txt */
export type TrapLine = Omit<FourLine, 'who'> & { who: FourLine['who'] | 'T' };
export const TRAP: TrapLine[] = [
  {"id": "c1-01", "who": 1, "write": null, "ms": {"kirill": 1959}, "text": "О, все тут? Всех слышно?"},
  {"id": "c1-02", "who": 2, "write": null, "ms": {"lera": 2377}, "text": "Слышно. Только у кого-то эхо."},
  {"id": "c1-03", "who": 4, "write": null, "ms": {"jane": 2377}, "text": "Это не эхо. Это брат за стенкой."},
  {"id": "c1-04", "who": 1, "write": null, "ms": {"kirill": 2952}, "text": "Ладно. Карточки по кругу. Кто первый?"},
  {"id": "c1-05", "who": 3, "write": null, "ms": {"alexander": 2560}, "text": "Давай ты. Ты всё равно уже командуешь."},
  {"id": "c1-06", "who": 1, "write": null, "ms": {"kirill": 9038}, "text": "Я не командую, я организую. Первая. А-бэ параллельна цэ-дэ, и а-бэ равно цэ-дэ. Первый признак. Да."},
  {"id": "c1-07", "who": 2, "write": null, "ms": {"lera": 5616}, "text": "Согласна. Вторая моя. Стороны попарно равны. Второй признак, тоже да."},
  {"id": "c1-08", "who": 3, "write": null, "ms": {"alexander": 7236}, "text": "Третья. А-бэ параллельна цэ-дэ, бэ-цэ равно а-дэ. Ну… да. Почти как первая."},
  {"id": "c1-09", "who": 1, "write": null, "ms": {"kirill": 1881}, "text": "Кидай в «да», быстрее закончим."},
  {"id": "c1-10", "who": 2, "write": null, "ms": {"lera": 7680}, "text": "Подождите. В первой одна и та же пара — и параллельна, и равна. А тут параллельна одна пара, а равна другая."},
  {"id": "c1-11", "who": 3, "write": null, "ms": {"alexander": 627}, "text": "И что?"},
  {"id": "c1-12", "who": 2, "write": null, "ms": {"lera": 2691}, "text": "Не знаю что. Но это не то же самое."},
  {"id": "c1-13", "who": 1, "write": null, "ms": {"kirill": 2273}, "text": "Ну нарисуй тогда, раз не то же."},
  {"id": "c1-14", "who": 2, "write": null, "ms": {"lera": 4023}, "text": "Сейчас… Нет. Опять параллелограмм получился."},
  {"id": "c1-15", "who": 1, "write": null, "ms": {"kirill": 2377}, "text": "Вот. Не получается — значит, да."},
  {"id": "c1-16", "who": 2, "write": null, "ms": {"lera": 3500}, "text": "Это значит, что у меня не получается. А не что «да»."},
  {"id": "c1-17", "who": 4, "write": null, "ms": {"jane": 2664}, "text": "Красиво сказано. Записываю в цитаты."},
  {"id": "c1-18", "who": 1, "write": null, "ms": {"kirill": 5956}, "text": "Слушайте, время идёт, а мы на третьей карточке. Давайте учителя позовём и дальше."},
  {"id": "c1-t0", "who": "T", "write": null, "ms": {"alena": 1959}, "text": "Да. Какие у вас вопросы?"},
  {"id": "c1-19", "who": 1, "write": null, "ms": {"kirill": 9038}, "text": "Карточка три. Очень похоже на первый признак, но не то же самое. А нарисовать, чтобы получился не параллелограмм, не можем."},
  {"id": "c1-ta1", "who": "T", "write": null, "ms": {"alena": 4989}, "text": "Это непростой вопрос. На него можно ответить, нарисовав то, что дано в условии."},
  {"id": "c1-ta2", "who": "T", "write": null, "ms": {"alena": 5460}, "text": "Смотрите. Нарисуем две параллельные прямые — ведь а-бэ параллельна цэ-дэ."},
  {"id": "c1-ta3", "who": "T", "write": null, "ms": {"alena": 2847}, "text": "На одной отметим а и бэ. Вот так."},
  {"id": "c1-ta4", "who": "T", "write": null, "ms": {"alena": 2429}, "text": "На другой — точку цэ. Например, здесь."},
  {"id": "c1-ta5", "who": "T", "write": null, "ms": {"alena": 4702}, "text": "Осталось понять, где может быть точка дэ, чтобы а-дэ равнялось бэ-цэ."},
  {"id": "c1-ta6", "who": "T", "write": null, "ms": {"alena": 1515}, "text": "Теперь подумайте сами."},
  {"id": "c1-20", "who": 2, "write": null, "ms": {"lera": 8882}, "text": "Точно, дэ может быть здесь и здесь. И когда здесь, это трапеция! Равнобокая. Боковые стороны равны, а основания параллельны."},
  {"id": "c1-tok", "who": "T", "write": null, "ms": {"alena": 1254}, "text": "Молодец, правильно."},
  {"id": "c1-21", "who": 3, "write": null, "ms": {"alexander": 4180}, "text": "Ой. И правда. Параллельна одна пара, а равна другая."},
  {"id": "c1-22", "who": 1, "write": null, "ms": {"kirill": 3814}, "text": "Ладно. Перекладываю в «не обязательно». Ты была права."},
  {"id": "c1-23", "who": 3, "write": null, "ms": {"alexander": 4937}, "text": "Четвёртая моя. Диагонали делятся пополам. Это третий признак. Да."},
  {"id": "c1-24", "who": 4, "write": null, "ms": {"jane": 5224}, "text": "Пятую и шестую — все вместе. Пятая: а-о равно о-цэ, а бэ-о не равно о-дэ."},
  {"id": "c1-25", "who": 2, "write": null, "ms": {"lera": 6609}, "text": "Тут осторожно. Если бы обе диагонали делились пополам — был бы параллелограмм. А тут только одна."},
  {"id": "c1-26", "who": 1, "write": null, "ms": {"kirill": 2873}, "text": "Значит, нет? Только теперь сразу с рисунком."},
  {"id": "c1-27", "who": 2, "write": null, "ms": {"lera": 6713}, "text": "Вот такой. Как воздушный змей. Одна диагональ делит другую пополам, а сама пополам не делится."},
  {"id": "c1-28", "who": 4, "write": null, "ms": {"jane": 1829}, "text": "Змей. А с хвостом можно?"},
  {"id": "c1-29", "who": 2, "write": null, "ms": {"lera": 1228}, "text": "Можно с хвостом."},
  {"id": "c1-30", "who": 3, "write": null, "ms": {"alexander": 5642}, "text": "Шестая. Противоположные углы равны. Это вроде свойство. А признака такого не было."},
  {"id": "c1-31", "who": 1, "write": null, "ms": {"kirill": 1437}, "text": "Значит, не обязательно?"},
  {"id": "c1-32", "who": 2, "write": null, "ms": {"lera": 7236}, "text": "После тройки я без рисунка ничего не кладу. Давайте нарисуем, где углы так равны, а это не параллелограмм."},
  {"id": "c1-33", "who": 4, "write": null, "ms": {"jane": 4415}, "text": "Не выходит. Все параллелограммы получаются, или углы не равны."},
  {"id": "c1-34", "who": 3, "write": null, "ms": {"alexander": 862}, "text": "У меня тоже."},
  {"id": "c1-35", "who": 1, "write": null, "ms": {"kirill": 1724}, "text": "Тогда да? Рискнём."},
  {"id": "c1-36", "who": 2, "write": null, "ms": {"lera": 2456}, "text": "Рискнём. Но я потом спрошу, почему."},
  {"id": "c1-37", "who": 4, "write": null, "ms": {"jane": 1776}, "text": "Всё, все шесть разложили."},
  {"id": "c1-38", "who": 1, "write": null, "ms": {"kirill": 5616}, "text": "Слушайте, время идёт, а мы на третьей карточке. Татьяна Алексеевна, можно вопрос?"},
  {"id": "c1-39", "who": 1, "write": null, "ms": {"kirill": 9038}, "text": "Карточка три. Очень похоже на первый признак, но не то же самое. А нарисовать, чтобы получился не параллелограмм, не можем."},
];

export const SIXTH: FourLine[] = [
  {"id": "c2-01", "who": 1, "write": null, "ms": {"anton": 2116}, "text": "Первая — да, первый признак."},
  {"id": "c2-02", "who": 2, "write": null, "ms": {"masha": 7210}, "text": "Вторая... Так... Какие у нас ещё признаки?... Это второй признак - переносим в да."},
  {"id": "c2-03", "who": 3, "write": null, "ms": {"ermil": 5642}, "text": "Третья — на первую похожа, только пара букв переставлена местами. Скорее всего - да."},
  {"id": "c2-04", "who": 1, "write": null, "ms": {"anton": 3422}, "text": "Тогда странно, а почему их в один признак не объединить?"},
  {"id": "c2-05", "who": 3, "write": null, "ms": {"ermil": 3396}, "text": "Не знаю, не догадались, наверно. Надо нарисовать."},
  {"id": "c2-06", "who": 3, "write": null, "ms": {"ermil": 7445}, "text": "Одна прямая... Вторая... Вот а-бэ. И одинаковая с ней цэ-дэ. Вроде как, параллелограмм."},
  {"id": "c2-07", "who": 1, "write": null, "ms": {"anton": 2743}, "text": "А если в другую сторону наклонить? Вот так."},
  {"id": "c2-08", "who": 3, "write": null, "ms": {"ermil": 3814}, "text": "Точно! Тогда не параллелограмм. Значит, третья — нет."},
  {"id": "c2-09", "who": 4, "write": null, "ms": {"dasha": 2952}, "text": "Четвёртая — да, это просто третий признак."},
  {"id": "c2-10", "who": 2, "write": null, "ms": {"masha": 3082}, "text": "Пятая. Диагонали — только одна пополам."},
  {"id": "c2-11", "who": 1, "write": null, "ms": {"anton": 4859}, "text": "Неверно, скорее всего. Это же от прошлого вопроса половину условия убрали."},
  {"id": "c2-12", "who": 3, "write": null, "ms": {"ermil": 6269}, "text": "Давай нарисую. Эта пополам. А этот не равен этому. Ну да, не похож на параллелограмм."},
  {"id": "c2-13", "who": 1, "write": null, "ms": {"anton": 5198}, "text": "Так, шестая. Угол а равен углу цэ, угол бэ равен углу дэ."},
  {"id": "c2-14", "who": 2, "write": null, "ms": {"masha": 4833}, "text": "Это свойство. Но признаков таких не было. Значит не обязательно?"},
  {"id": "c2-15", "who": 3, "write": null, "ms": {"ermil": 3422}, "text": "Если не обязательно, надо пример нарисовать. Нарисуй."},
  {"id": "c2-16", "who": 2, "write": null, "ms": {"masha": 9639}, "text": "Сейчас попробую. Вот первый угол. От этого луча второй. От этого — третий под таким же углом. Не, четвёртый угол первому не равен."},
  {"id": "c2-17", "who": 1, "write": null, "ms": {"anton": 10031}, "text": "Может, по-другому? Нарисую сразу равные противоположные углы. Один... второй... Тут они пересекаются. Тоже оставшиеся углы не равны."},
  {"id": "c2-18", "who": 3, "write": null, "ms": {"ermil": 1672}, "text": "Да как это нарисовать-то можно?"},
  {"id": "c2-19", "who": 1, "write": null, "ms": {"anton": 3135}, "text": "Аня, а ты что думаешь? Ты что-то совсем молчишь."},
  {"id": "c2-20", "who": 4, "write": null, "ms": {"dasha": 6635}, "text": "Тоже пока не знаю. Может, просто посчитать? Ну углов четыре, вместе — триста шестьдесят."},
  {"id": "c2-21", "who": 1, "write": null, "ms": {"anton": 1646}, "text": "Да, но это везде так."},
  {"id": "c2-22", "who": 4, "write": null, "ms": {"dasha": 5825}, "text": "А равен цэ, бэ равен дэ. Значит, а плюс бэ — это половина. Сто восемьдесят."},
  {"id": "c2-23", "who": 2, "write": null, "ms": {"masha": 1959}, "text": "Интересно, и что с этого?"},
  {"id": "c2-24", "who": 4, "write": null, "ms": {"dasha": 9509}, "text": "А и бэ стоят на одной стороне а-бэ. Если в сумме сто восемьдесят — это односторонние углы. Значит, а-дэ параллельна бэ-цэ."},
  {"id": "c2-25", "who": 3, "write": null, "ms": {"ermil": 2900}, "text": "Точно! Эврика! А со второй парой так же!"},
  {"id": "c2-26", "who": 4, "write": null, "ms": {"dasha": 4441}, "text": "Так же. Обе пары параллельны. Это просто параллелограмм по определению."},
  {"id": "c2-27", "who": 1, "write": null, "ms": {"anton": 1306}, "text": "Шестая — да!"},
  {"id": "c2-28", "who": 2, "write": null, "ms": {"masha": 1829}, "text": "Ура! Шесть из шести!"},
  {"id": "c2-29", "who": 3, "write": null, "ms": {"ermil": 1045}, "text": "Давайте пятюню!"},
  {"id": "c2-30", "who": 1, "write": null, "ms": {"anton": 2038}, "text": "Аня, что ты раньше молчала?"},
  {"id": "c2-31", "who": 4, "write": null, "ms": {"dasha": 3997}, "text": "Тоже не знала, как решать. Только когда начала объяснять, все сложилось."},
];

export const CHOCOLATE: DialogueLine[] = [
  {"id": "p1-01", "who": 2, "write": null, "ms": {"alexander": 2273}, "text": "Привет. Ну что, сверяемся?"},
  {"id": "p1-02", "who": 1, "write": null, "ms": {"kirill": 1620}, "text": "Давай. У тебя сколько?"},
  {"id": "p1-03", "who": 2, "write": null, "ms": {"alexander": 7236}, "text": "Пять. Стороны, диагонали, угол. А у тебя… Ты чего так написал? Как курица лапкой."},
  {"id": "p1-04", "who": 1, "write": null, "ms": {"kirill": 5642}, "text": "Да я без планшета сегодня. Мы к тёте в гости приехали, с её компа мышкой рисую."},
  {"id": "p1-05", "who": 2, "write": null, "ms": {"alexander": 1698}, "text": "Понятно, ладно, разберу."},
  {"id": "p1-06", "who": 2, "write": null, "ms": {"alexander": 8411}, "text": "Так. А-дэ равно бэ-цэ — есть. А-бэ равно цэ-дэ — есть. Углы есть… А это что? А-бэ равно а-о?"},
  {"id": "p1-07", "who": 1, "write": null, "ms": {"kirill": 2900}, "text": "Ну да. Посмотри на чертёж — одинаковые."},
  {"id": "p1-08", "who": 2, "write": null, "ms": {"alexander": 3291}, "text": "Хм, похожи, конечно. Но мне кажется, что они не равны."},
  {"id": "p1-09", "who": 1, "write": null, "ms": {"kirill": 3239}, "text": "Почему не равны? Палец приложи — одинаковые."},
  {"id": "p1-10", "who": 2, "write": null, "ms": {"alexander": 9273}, "text": "Да как я его тут приложу? Я ещё вот по клеткам смотрю. А-бэ — это два вправо, четыре вверх. А-о — пять вправо, два вверх. Разные."},
  {"id": "p1-11", "who": 1, "write": null, "ms": {"kirill": 9848}, "text": "Как ты так сравниваешь? У тебя и вправо, и вверх разное количество каждый раз. А длина может быть одна и та же. Наискосок ведь."},
  {"id": "p1-12", "who": 2, "write": null, "ms": {"alexander": 3866}, "text": "Нет. Так не бывает. Да и видно, что разные немного."},
  {"id": "p1-13", "who": 1, "write": null, "ms": {"kirill": 1724}, "text": "А мне видно, что одинаковые."},
  {"id": "p1-14", "who": 2, "write": null, "ms": {"alexander": 1332}, "text": "Ну и как мы узнаем?"},
  {"id": "p1-15", "who": 1, "write": null, "ms": {"kirill": 2273}, "text": "Не знаю. Давай учителя позовём."},
  {"id": "p1-16", "who": 2, "write": null, "ms": {"alexander": 627}, "text": "Давай."},
  {"id": "p1-17", "who": 2, "write": null, "ms": {"alexander": 8934}, "text": "Мы сверяемся: у Миши записано, что а-бэ равно а-о, а я думаю, что не равны, раз по клеткам вправо и вверх не совпадают. Как правильно?"},
  {"id": "p1-18", "who": 2, "write": null, "ms": {"alexander": 3422}, "text": "Два в квадрате плюс четыре в квадрате… двадцать."},
  {"id": "p1-19", "who": 1, "write": null, "ms": {"kirill": 8803}, "text": "А пять в квадрате плюс два в квадрате — двадцать девять. Да, точно, не равны. Ладно, теперь понятно. Вычёркиваю."},
  {"id": "p1-20", "who": 2, "write": null, "ms": {"alexander": 1541}, "text": "Видишь, я же говорил."},
  {"id": "p1-21", "who": 1, "write": null, "ms": {"kirill": 9482}, "text": "Ты говорил, что вправо-вверх не совпадает, значит, не равны. А бывает, что не совпадает, а длина одна. Просто тут не совпало."},
  {"id": "p1-22", "who": 2, "write": null, "ms": {"alexander": 3814}, "text": "Ну… да. По одним клеткам не скажешь, посчитать надо."},
  {"id": "p1-23", "who": 1, "write": null, "ms": {"kirill": 5512}, "text": "Давай теперь общий список. По очереди: кто сказал, тот и пишет. Начинай."},
  {"id": "p1-24", "who": 2, "write": "AD = BC", "ms": {"alexander": 1332}, "text": "А-дэ равно бэ-цэ."},
  {"id": "p1-25", "who": 1, "write": "AB = CD", "ms": {"kirill": 1254}, "text": "А-бэ равно цэ-дэ."},
  {"id": "p1-26", "who": 2, "write": "AO = OC", "ms": {"alexander": 3657}, "text": "А-о равно о-цэ. Пять и два, пять и два — тут не поспоришь."},
  {"id": "p1-27", "who": 1, "write": "BO = OD", "ms": {"kirill": 4415}, "text": "Бэ-о равно о-дэ. Три и два, три и два. Этого у меня не было."},
  {"id": "p1-28", "who": 2, "write": "∠A = ∠C", "ms": {"alexander": 1855}, "text": "Угол а равен углу цэ."},
  {"id": "p1-29", "who": 1, "write": "∠B = ∠D", "ms": {"kirill": 3866}, "text": "И угол бэ равен углу дэ. А этого не было у тебя."},
  {"id": "p1-30", "who": 2, "write": null, "ms": {"alexander": 1593}, "text": "Всё равно шесть получилось."},
  {"id": "p1-31", "who": 1, "write": null, "ms": {"kirill": 1541}, "text": "Только теперь все честные."},
  {"id": "p1-32", "who": 1, "write": null, "ms": {"kirill": 2325}, "text": "Ой, здравствуйте, Татьяна Алексеевна."},
  {"id": "p1-33", "who": 1, "write": null, "ms": {"kirill": 8411}, "text": "Татьяна Алексеевна, а у меня записано, что а-бэ равно а-о. На глаз одинаковые, а по клеткам разные. Как правильно?"},
  {"id": "p1-tq", "who": "T", "write": null, "ms": {"alena": 1202, "filipp": 1176}, "text": "Какой у вас вопрос?"},
  {"id": "p1-ta", "who": "T", "write": null, "ms": {"alena": 18808, "filipp": 20245}, "text": "Мы не можем утверждать, что отрезки равны, потому что так кажется из чертежа. Но то, что количество клеток вправо и вверх не совпадает, тоже не доказательство, что а-бэ не равно а-о, тут Миша прав. Вспомните теорему Пифагора: клетки — это катеты, а ваши отрезки — гипотенузы. Посчитайте."},
];

/** A point of the figure in cells: A is (0, 0), x to the right, y up; B (2, 4), C (10, 4), D (8, 0), O (5, 2) */
export type Pt = [number, number];
/** Drawn while a line is said, `at` that part of the way through it: a broken line, a right-angle mark
 *  (corner, then a point on each side), a filled triangle, a number */
/** ticks: equal segments marked, [from, to, how many strokes] */
export interface Draw { at: number; path?: Pt[]; angle?: [Pt, Pt, Pt]; fill?: Pt[]; label?: { at: Pt; text: string }; ticks?: [Pt, Pt, number][] }

